    .mat-menu-panel {
        min-width: 112px;
        max-width: 280px;
        overflow: auto;
        -webkit-overflow-scrolling: touch;
        max-height: calc(100vh - 48px);
        border-radius: 4px;
        outline: 0;
        min-height: 64px;
    }

    .mat-menu-panel.ng-animating {
        pointer-events: none;
    }

    .cdk-high-contrast-active .mat-menu-panel {
        outline: solid 1px;
    }

    .mat-menu-content:not(:empty) {
        padding-top: 8px;
        padding-bottom: 8px;
    }

    .mat-menu-item {
        -webkit-user-select: none;
        -moz-user-select: none;
        -ms-user-select: none;
        user-select: none;
        cursor: pointer;
        outline: none;
        border: none;
        -webkit-tap-highlight-color: transparent;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        display: block;
        line-height: 48px;
        height: 48px;
        padding: 0 16px;
        text-align: left;
        text-decoration: none;
        max-width: 100%;
        position: relative;
    }

    .mat-menu-item::-moz-focus-inner {
        border: 0;
    }

    .mat-menu-item[disabled] {
        cursor: default;
    }

    [dir="rtl"] .mat-menu-item {
        text-align: right;
    }

    .mat-menu-item .mat-icon {
        margin-right: 16px;
        vertical-align: middle;
    }

    .mat-menu-item .mat-icon svg {
        vertical-align: top;
    }

    [dir="rtl"] .mat-menu-item .mat-icon {
        margin-left: 16px;
        margin-right: 0;
    }

    .mat-menu-item[disabled] {
        pointer-events: none;
    }

    .cdk-high-contrast-active .mat-menu-item {
        margin-top: 1px;
    }

    .cdk-high-contrast-active .mat-menu-item.cdk-program-focused,
    .cdk-high-contrast-active .mat-menu-item.cdk-keyboard-focused,
    .cdk-high-contrast-active .mat-menu-item-highlighted {
