    .mat-card {
        transition: box-shadow 280ms cubic-bezier(0.4, 0, 0.2, 1);
        display: block;
        position: relative;
        padding: 16px;
        border-radius: 4px;
    }

    ._mat-animation-noopable.mat-card {
        transition: none;
        animation: none;
    }

    .mat-card .mat-divider-horizontal {
        position: absolute;
        left: 0;
        width: 100%;
    }

    [dir="rtl"] .mat-card .mat-divider-horizontal {
        left: auto;
        right: 0;
    }

    .mat-card .mat-divider-horizontal.mat-divider-inset {
        position: static;
        margin: 0;
    }

    [dir="rtl"] .mat-card .mat-divider-horizontal.mat-divider-inset {
        margin-right: 0;
    }

    .cdk-high-contrast-active .mat-card {
        outline: solid 1px;
    }

    .mat-card-actions,
    .mat-card-subtitle,
    .mat-card-content {
        display: block;
        margin-bottom: 16px;
    }

    .mat-card-title {
        display: block;
        margin-bottom: 8px;
    }

    .mat-card-actions {
        margin-left: -8px;
        margin-right: -8px;
        padding: 8px 0;
    }

    .mat-card-actions-align-end {
        display: flex;
        justify-content: flex-end;
    }

    .mat-card-image {
        width: calc(100% + 32px);
        margin: 0 -16px 16px -16px;
    }

    .mat-card-footer {
        display: block;
        margin: 0 -16px -16px -16px;
    }

    .mat-card-actions .mat-button,
    .mat-card-actions .mat-raised-button,
    .mat-card-actions .mat-stroked-button {
        margin: 0 8px;
    }

    .mat-card-header {
        display: flex;
        flex-direction: row;
    }

    .mat-card-header .mat-card-title {
        margin-bottom: 12px;
    }

    .mat-card-header-text {
        margin: 0 16px;
    }

    .mat-card-avatar {
        height: 40px;
        width: 40px;
        border-radius: 50%;
        flex-shrink: 0;
        object-fit: cover;
    }

    .mat-card-title-group {
        display: flex;
        justify-content: space-between;
    }

    .mat-card-sm-image {
        width: 80px;
        height: 80px;
    }

    .mat-card-md-image {
        width: 112px;
        height: 112px;
    }

    .mat-card-lg-image {
        width: 152px;
        height: 152px;
    }

    .mat-card-xl-image {
        width: 240px;
        height: 240px;
        margin: -8px;
    }

    .mat-card-title-group>.mat-card-xl-image {
        margin: -8px 0 8px;
    }

