   --swal2-footer-border-color: #eee;
   --swal2-footer-background: transparent;
   --swal2-footer-color: inherit;
   --swal2-timer-progress-bar-background: rgba(0, 0, 0, 0.3);
   --swal2-close-button-position: initial;
