   clip: rect(0, 0, 0, 0);
   width: 1px;
   height: 1px;
   margin: -1px;
   padding: 0;
   border: 0
 }

 .selectr-visible {
   position: absolute;
   left: 0;
   top: 0;
   width: 100%;
   height: 100%;
   opacity: 0;
   z-index: 11
 }

 .selectr-desktop.multiple .selectr-visible {
   display: none
 }

 .selectr-desktop.multiple.native-open .selectr-visible {
   top: 100%;
   min-height: 200px !important;
