   border: 1px solid #999;
   border-radius: 3px;
   background-color: #fff
 }

 .selectr-selected:before {
   position: absolute;
   top: 50%;
   right: 10px;
   width: 0;
   height: 0;
   content: "";
   transform: rotate(0) translate3d(0, -50%, 0);
   border-color: #6c7a86 #0000 #0000;
