 .selectr-input-clear,
 .selectr-tag-remove {
   position: absolute;
   top: 50%;
   right: 22px;
   width: 20px;
   height: 20px;
   padding: 0;
   cursor: pointer;
   transform: translate3d(0, -50%, 0);
   border: none;
   background-color: initial;
   z-index: 11
 }

