 .ph-item {
   direction: ltr;
   position: relative;
   display: flex;
   flex-wrap: wrap;
   padding: 30px 15px 15px;
   overflow: hidden;
   margin-bottom: 30px;
   background-color: #fff;
   border: 1px solid #e6e6e6;
   border-radius: 2px
 }

 .ph-item,
 .ph-item *,
 .ph-item:after,
 .ph-item:before {
   box-sizing: border-box
 }

 .ph-item:before {
   content: " ";
   position: absolute;
   top: 0;
   right: 0;
   bottom: 0;
   left: 50%;
   z-index: 1;
   width: 500%;
   margin-left: -250%;
   animation: phAnimation .8s linear infinite;
   background: linear-gradient(90deg, #fff0 46%, #ffffff59 50%, #fff0 54%) 50% 50%
 }

 .ph-item>* {
   flex: 1 1 auto;
   display: flex;
   flex-flow: column;
   padding-right: 15px;
   padding-left: 15px
 }

 .ph-row {
   display: flex;
   flex-wrap: wrap;
   margin-bottom: 7.5px
 }

 .ph-row div {
   height: 10px;
   margin-bottom: 7.5px;
   background-color: #ced4da
 }

