   content: " ";
   display: block;
   padding-top: 100%
 }

 .ph-picture {
   width: 100%;
   height: 120px;
   background-color: #ced4da;
   margin-bottom: 15px
 }

 @keyframes phAnimation {
   0% {
     transform: translate3d(-30%, 0, 0)
   }

   to {
     transform: translate3d(30%, 0, 0)
   }
 }

