 .table table {
   width: 100%;
   border-collapse: collapse;
   border-radius: 5px;
   margin: 0 0 35px
 }

 .table table th {
   background: #e8e8e8;
   border: 2px solid #fff;
   text-align: left;
   padding: 12px
 }

 .table table td {
   padding: 12px;
   border-bottom: 1px solid #00000026
 }

 .table table td:first-of-type {
   border-right: 1px solid #00000026
 }

 .table table td.red {
   color: #c62828
 }

 .table table td.yellow {
   color: #ffb300
 }

 .table table td.green {
   color: #43a047
 }

 .table table .cnae-status {
   font-weight: 700
 }

 .table-print table {
   width: 100%;
   border-collapse: collapse;
   border-radius: 5px;
   margin: 0 0 35px;
