   height: 1px;
   margin: -1px;
   overflow: hidden;
   padding: 0;
   position: absolute;
   width: 1px
 }

 .p-hidden-accessible input,
 .p-hidden-accessible select {
   transform: scale(0)
 }

 .p-reset {
   margin: 0;
   padding: 0;
   border: 0;
   outline: 0;
   text-decoration: none;
   font-size: 100%;
   list-style: none
 }

 .p-disabled,
 .p-disabled * {
   cursor: default !important;
   pointer-events: none
 }

 .p-component-overlay {
   position: fixed;
   top: 0;
   left: 0;
   width: 100%;
   height: 100%
 }

 .p-overflow-hidden {
   overflow: hidden
 }

 .p-unselectable-text {
   -webkit-user-select: none;
   user-select: none
 }

 .p-scrollbar-measure {
   width: 100px;
   height: 100px;
   overflow: scroll;
   position: absolute;
   top: -9999px
 }

 @keyframes p-fadein {
   0% {
     opacity: 0
   }

   to {
     opacity: 1
   }
 }

 button,
 input[type=button],
 input[type=file]::-webkit-file-upload-button,
 input[type=reset],
 input[type=submit] {
   border-radius: 0
 }

 .p-link {
   text-align: left;
   background-color: initial;
   margin: 0;
   padding: 0;
   border: 0;
   cursor: pointer;
   -webkit-user-select: none;
   user-select: none
 }

 .p-sr-only {
   border: 0;
   clip: rect(1px, 1px, 1px, 1px);
   clip-path: inset(50%);
   height: 1px;
   margin: -1px;
   overflow: hidden;
   padding: 0;
   position: absolute;
   width: 1px;
   word-wrap: normal !important
 }

 .p-connected-overlay {
   opacity: 0;
   transform: scaleY(.8);
   transition: transform .12s cubic-bezier(0, 0, .2, 1), opacity .12s cubic-bezier(0, 0, .2, 1)
 }

 .p-connected-overlay-visible {
   opacity: 1;
   transform: scaleY(1)
 }

 .p-connected-overlay-hidden {
   opacity: 0;
   transform: scaleY(1);
   transition: opacity .1s linear
