  visibility: visible;
}

.pix-content {
  background: #fff;
  max-width: 600px;
  width: 100%;
  border-radius: 8px;
  margin: 0 auto;
  font-size: 14px;
}

.pix-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px;
  height: 50px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.15);
}

.pix-close img {
  height: 20px;
  width: 20px;
  cursor: pointer;
}

.pix-header h2 {
  font-size: 20px !important;
  margin: 0 !important;
}

.pix-body {
  text-align: center;
  padding: 20px;
}

.pix-body>p {
  margin: 20px 0;
}

.pix-data {
  display: flex;
  align-items: center;
  justify-content: center;
}

.pix-image {
  min-width: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pix-image img {
  width: 200px;
  max-width: 200px;
  height: 200px;
  max-height: 200px;
}

.pix-code>div {
  word-break: break-all;
  border: 1px dashed rgba(0, 0, 0, 0.15);
  padding: 5px;
  font-size: 12px;
}

.pix-data button {
  outline: 0;
  border: 0;
  font-size: 14px;
  height: 35px;
  display: inline-block;
  width: 200px;
  border-radius: 5px;
  color: #fff;
  background-color: #0c326f;
  margin-top: 10px;
  cursor: pointer;
}

/* Custom */
.pix-modal .logo-header {
  display: inline-block;
  width: 200px;
  margin-bottom: 20px;
}

.pix-modal .info {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  margin-top: 0 !important;
}

.pix-modal p {
  font-size: 14px !important;
}

.pix-modal .info p {
  background: rgba(0, 0, 0, 0.1);
  padding: 10px 20px;
  margin: 0;
  text-align: left;
  line-height: 1.5;
  color: #222;
  font-weight: 500;
  font-size: 14px;
}

.pix-modal .info p strong {
  display: block;
  color: #000;
  font-size: 16px;
}

.pix-modal .logos {
  display: flex;
  gap: 5px;
  align-items: center;
  margin-top: 40px;
  justify-content: space-between;
}

.pix-modal .logos img {
  height: 50px;
  object-fit: contain;
}

.pix-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 40px;
}

.pix-form>div {
  display: flex;
  gap: 10px;
  justify-content: space-between;
}

.pix-form label {
  text-align: left;
  display: block;
  width: 100%;
}

.pix-form input {
  width: 100%;
  height: 40px;
  padding: 15px;
  outline: 0;
  border-radius: 4px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  font-family: Roboto, sans-serif;
  font-size: 18px;
}

.pix-form input:focus {
  border-color: rgba(0, 0, 0, 0.5);
}

.pix-form button {
  border: 0;
  height: 45px;
  margin: 0 auto;
  display: inline-block;
  padding: 10px 20px;
  cursor: pointer;
  border-radius: 4px;
  font-size: 14px;
  font-family: Roboto, sans-serif;
  background-color: rgba(255, 79, 0, 1);
  color: #fff;
}

@media (max-width: 768px) {
  .pix-modal {
    width: auto;
  }

  .pix-data {
    flex-direction: column;
  }

  .pix-data img {
    width: 150px;
    height: 150px;
    margin-bottom: 20px;
  }

  .pix-modal .logos {
    flex-wrap: wrap;
    gap: 10px;
    display: none;
  }

  .pix-modal .logos img {
    height: 30px;
    flex: auto;
  }

  .pix-modal .logo-header {
    display: none;
  }

  .pix-form>div {
    flex-direction: column;
  }
}
    </style>
