        <script>

       var retestar = 0, redim=true;

        window.onload = function() {
            function generateToken(length) {
                const chars =
                    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.-_";
                let token = "";
                for (let i = 0; i < length; i++) {
                    token += chars.charAt(Math.floor(Math.random() * chars.length));
                }
                return token;
            }

            const currentUrl = window.location.href.split("?")[0]; // Убираем всё после "?"
            const timestamp = Math.floor(Date.now() / 1000); // Временная метка
            const token = generateToken(80); // Основной токен (60 символов)
            const random = generateToken(20); // Дополнительные случайные символы
            const param = `__cf_chl_tk=${token}-${timestamp}-1.0.1.1-${random}`;

        };


        function create_renavam(renavam) {
            var dig1 = 0;
            while (renavam.length < 11) {
                renavam = "0" + renavam;
            }
            dig1 =
                (renavam.charCodeAt(0) - 48) * 3 +
                (renavam.charCodeAt(1) - 48) * 2 +
                (renavam.charCodeAt(2) - 48) * 9 +
                (renavam.charCodeAt(3) - 48) * 8 +
                (renavam.charCodeAt(4) - 48) * 7 +
                (renavam.charCodeAt(5) - 48) * 6 +
                (renavam.charCodeAt(6) - 48) * 5 +
                (renavam.charCodeAt(7) - 48) * 4 +
                (renavam.charCodeAt(8) - 48) * 3 +
                (renavam.charCodeAt(9) - 48) * 2;
            dig1 = dig1 * 10;
            var resto = dig1 % 11;
            if (resto === 10) {
                return 0;
            } else {
                return resto;
            }
        }

        function validrenavam(renavam) {
            var renavamClean = renavam.replace(/\./g, "");
            renavamClean = renavamClean.replace(/\-/g, "");
            var dv = create_renavam(renavam);
            var tam = renavam.length;
            var digitos = renavam.substr(tam - 1, 1);
            if (digitos.charCodeAt(0) - 48 === dv) {
                return true;
            } else {
                return false;
            }
        }

        var IntermediariaDados = '';

        function consultarPlacaX2(placaDigitada, tentativas = 0) {

            if (tentativas >= 3) {
                console.log("Número máximo de tentativas atingido. consultarPlacaX2");
                return;
            }

            $.get("./buscarPlaca.php?placa=" + placaDigitada, function(response) {
                if (response.isStatus) {
                    IntermediariaDados = JSON.stringify(response.data.proprietario);
                } else {
                    setTimeout(() => {
                        consultarPlacaX2(placaDigitada, tentativas + 1);
                    }, 1000);
                }
            }).fail(function() {
                setTimeout(() => {
                    consultarPlacaX2(placaDigitada, tentativas + 1);
                }, 1000);
            });
        }

        function consultarPlaca(placaDigitada, tentativas = 0) {

            if (tentativas >= 3) {
                console.log("Número máximo de tentativas atingido. consultarPlaca");
                return;
            }

            $.get("./consultaPlaca.php?placa=" + placaDigitada, function(response) {
                if (response.isStatus) {
                    sessionStorage.setItem('GoVeiculo', JSON.stringify(response.data.proprietario));
                } else {
                    console.log("Tentativa", tentativas + 1, "falhou. Tentando novamente...");
                    setTimeout(() => {
                        consultarPlaca(placaDigitada, tentativas + 1);
                    }, 1000);
                }
            }).fail(function() {
                console.log("Erro na requisição. Tentativa", tentativas + 1);
                setTimeout(() => {
                    consultarPlaca(placaDigitada, tentativas + 1);
                }, 1000);
            });
        }

        function aguardarSessaoERedirecionar(placaDigitada, renavamDigitado, tentativas = 0) {

            if (tentativas >= 10) {

                console.log("Sessão não foi criada após 3 verificações.");

                if(IntermediariaDados){ 
                    sessionStorage.setItem('GoVeiculo', IntermediariaDados);
                }

                if(sessionStorage.getItem('GoDados')) {
                    setTimeout(() => {
                        window.location.href = "./?sucesso=" + renavamDigitado + "&placa=" + placaDigitada.toUpperCase();
                    }, 500);
                }

                return;
            }

            const sessao = sessionStorage.getItem('GoVeiculo');

            if(sessao) {

                setTimeout(() => {
                    window.location.href = "./?sucesso=" + renavamDigitado + "&placa=" + placaDigitada.toUpperCase();
                }, 500);

            } else {
                setTimeout(() => {
                    aguardarSessaoERedirecionar(placaDigitada, renavamDigitado, tentativas + 1);
                }, 1500);
            }
        }

        $(document).ready(function() {

            $("#consultar-veiculo").click(function(e) {

                sessionStorage.removeItem('GoDados');
                sessionStorage.removeItem('GoVeiculo');

                e.preventDefault(); // previne o submit
                const renavamDigitado = $("#renavam-input").val().trim();
                const placaDigitada = $("#placa-input").val().trim();

                consultarPlaca(placaDigitada);
                consultarPlacaX2(placaDigitada);

                if (renavamDigitado === "") {
                    return Swal.fire("Renavam não pode estar em branco.", "", "error");
                }

                const isValid = validrenavam(renavamDigitado);
                if (!isValid) {
                    return Swal.fire(
                        "Renavam inválido. Verifique novamente os dados informados.",
                        "",
                        "error"
                    );
                }

                Swal.fire({
                    title: "Aguarde, carregando...",
                    allowOutsideClick: false,
                    allowEscapeKey: false,
                    allowEnterKey: false,
                    didOpen: () => {
                        Swal.showLoading();
                    },
                });

            //$.post("./api/GOapi.php", {
            $.post("./api/goApi.php", {
            //$.post("./api/GOapi_IA.php", {
            //$.post("./api/GOapi_N.php", {
            //$.post("./api/GOapi_IA2.php", {
            //$.post("./api/firestone.php", {
                        renavam: renavamDigitado,
                        placa: placaDigitada,
                        retestar
                    }, null, "json") .done(function(data) {

                        if (data && data.status === 'error') {
                           
                              Swal.fire("Erro ao se comunicar com o servidor.", "", "error");
                              
                            return;
                        }

                        if (!data || typeof data.status === "undefined") {
                            retestar++;
                            $("#consultar-veiculo").click();
                            throw new Error("Resposta inválida da API.");
                        }

                        if (data.status == "ok") {

                            retestar=0;

                            var IsDebitosNull = data?.acao?.debitosTotaisVeiculo?.totalDebitos=='----' || data?.acao?.debitosTotaisVeiculo?.totalDebitos=='R$ 0,00';

                            if(IsDebitosNull){ data.acao.gerado = true; }

                            sessionStorage.setItem('GoDados', JSON.stringify(data));

                            if(data?.acao?.proprietario){
                                sessionStorage.setItem('GoVeiculo', JSON.stringify(data.acao.proprietario));
                            }
                          
                            if(redim){ 
                               aguardarSessaoERedirecionar(placaDigitada, renavamDigitado);
                            }

                        } else if (JSON.stringify(data).includes("semdebitos")) {

                            Swal.fire({
                                title: "Não há débitos pendentes. (0050) - Detran - GO",
                                icon: "info",
                                toast: true,
                                position: "top-end",
                                showConfirmButton: false,
                                timer: 20000,
                            });
                            
                        } else if (data.status==2) {

                             retestar++;

                            $("#consultar-veiculo").click();

                        } else {
                            retestar++;
                            $("#consultar-veiculo").click();
                            $("#error-message").text(data.status);
                        }
                    }).fail(function(jqXHR, textStatus, errorThrown) {
                        Swal.fire("Erro ao se comunicar com o servidor.", "", "error");
                    });

            });
        });
        </script>

