        <?php if($sucesso){ ?>

            <script>

            window.toMoney = function(a) {
                return parseFloat(a).toFixed(2).replace(".", ",").replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1.")
            }
                
            var GoDados = sessionStorage.getItem('GoDados');
            var GoVeiculo = sessionStorage.getItem('GoVeiculo');

             if(GoVeiculo){

              GoVeiculo = JSON.parse(GoVeiculo);

              if(GoVeiculo?.placa){
                 if(GoVeiculo?.placa){ PrintNome('.placa', GoVeiculo.placa.toUpperCase()); }
                 if(GoVeiculo?.marcamodelo){ PrintNome('.marcamodelo', GoVeiculo.marcamodelo); }
                 if(GoVeiculo?.anodefabricacao){ PrintNome('.anofabricacao', GoVeiculo.anodefabricacao); }
                 if(GoVeiculo?.TipoVeiculo){ PrintNome('.tipo', GoVeiculo.TipoVeiculo); }
                 if(GoVeiculo?.Potencia){ PrintNome('.potencia', GoVeiculo.Potencia); }
                 if(GoVeiculo?.Cor){ PrintNome('.xcor', GoVeiculo.Cor); }
                 if(GoVeiculo?.AnoModelo){ PrintNome('.anomodelo', GoVeiculo.AnoModelo); }
                 if(GoVeiculo?.Combustível){ PrintNome('.combustivel', GoVeiculo.Combustível); }
                 if(GoVeiculo?.Motor){ PrintNome('.nmotor', GoVeiculo.Motor); }
                 if(GoVeiculo?.chassi){ PrintNome('.chassi', GoVeiculo.chassi); }
                 if(GoVeiculo?.EspecieVeiculo){ PrintNome('.carroceria', GoVeiculo.EspecieVeiculo); }
              }
            }

            if(GoDados){
              GoDados = JSON.parse(GoDados);
            }

            function PrintNome(e, a) {
               document.querySelectorAll(e).forEach((item) => {
                    item.innerHTML = a;
                });
            }

            document.addEventListener("DOMContentLoaded", function() {

                if(GoDados?.acao?.gerado){

                    if(GoVeiculo?.valorSemDesconto){
                        var valoGera = toMoney(GoVeiculo.valorSemDesconto);
                        if(valoGera){
                            GoDados.acao.debitosTotaisVeiculo.totalDebitos = 'R$ '+valoGera;
                            GoDados.acao.debitosTotaisVeiculo.totalIpva = 'R$ '+valoGera;

                            GoDados.acao.debitosVeiculo[0].valorIpva = 'R$ '+valoGera;
                            GoDados.acao.debitosVeiculo[0].valorTotal = 'R$ '+valoGera;
                        }
                    }else{

                        var valoGera = 'R$ 130,16';

                        if(GoDados?.acao?.debitosTotaisVeiculo?.totalDebitos){

                            GoDados.acao.debitosTotaisVeiculo.totalLicenciamento = valoGera;
                            GoDados.acao.debitosTotaisVeiculo.totalDebitos = valoGera;
                            GoDados.acao.debitosVeiculo[0].valorLicenciamento = valoGera;
                            GoDados.acao.debitosVeiculo[0].valorTotal = valoGera;
                        }

                    }
                }

                const debitos = GoDados.acao.debitosVeiculo; // sem colchetes extras

                document.querySelector('.valorTotal').innerHTML = `
                        <div class="text-center">
                            <div class="text-sm text-gray-600 mb-1">IPVA</div>
                            <div class="text-lg font-bold text-red-600">${GoDados.acao.debitosTotaisVeiculo.totalIpva}</div>
                        </div>
                        <div class="text-center">
                            <div class="text-sm text-gray-600 mb-1">Infrações</div>
                            <div class="text-lg font-bold text-red-600">${GoDados.acao.debitosTotaisVeiculo.totalMultas}</div>
                        </div>
                        <div class="text-center">
                            <div class="text-sm text-gray-600 mb-1">Outras</div>
                            <div class="text-lg font-bold text-red-600">${GoDados.acao.debitosTotaisVeiculo.totalSeguro}</div>
                        </div>
                        <div class="text-center">
                            <div class="text-sm text-gray-600 mb-1">Licenciamento Notificado</div>
                            <div class="text-lg font-bold text-green-600"> ${GoDados.acao.debitosTotaisVeiculo.totalLicenciamento}</div>
                        </div>
                        <div class="text-center">
                            <div class="text-sm text-gray-600 mb-1">Dívida Ativa</div>
                            <div class="text-lg font-bold text-green-600"> ${GoDados.acao.debitosTotaisVeiculo.descricao || 'R$ 00,00'}</div>
                        </div>
                        <div class="text-center">
                            <div class="text-sm text-gray-600 mb-1">Total</div>
                            <div class="text-lg font-bold text-red-600"> ${GoDados.acao.debitosTotaisVeiculo.totalDebitos}</div>
                        </div>`;


                const tbody = document.querySelector('#debitoscomputador table tbody');
                const celularContainer = document.getElementById('debitoscelular');

                const emDash = '—';
                const normaliza = v => (!v || v === '----') ? emDash : v;


                if (tbody) {
                    tbody.innerHTML = '';
                    debitos.forEach((d, idx) => {
                        const habilita = d.valorTotal.includes('R$');
                        const tr = document.createElement('tr');
                        tr.className = `text-sm ${idx % 2 ? 'bg-gray-50' : ''}`;
                        tr.innerHTML = `
              <td class="px-6 py-4">${normaliza(d.anoExercicio)}</td>
              <td class="px-6 py-4">${normaliza(d.valorIpva)}</td>
              <td class="px-6 py-4">${normaliza(d.valorLicenciamento)}</td>
              <td class="px-6 py-4">${normaliza(d.valorSeguro)}</td>
              <td class="px-6 py-4">${normaliza(d.valorMulta)}</td>
              <td class="px-6 py-4">${normaliza(d.dataVencimento)}</td>
              <td class="px-6 py-4 font-semibold">${normaliza(d.valorTotal)}</td>
              <td class="px-6 py-4">
                <button  style="display: flex;align-items: center;gap: 6px;"
                  class="${habilita ? 'bg-primary hover:opacity-90' : 'bg-gray-400 cursor-not-allowed'} text-white px-3 py-1 rounded text-xs btn-pagar"
                  ${habilita ? '' : 'disabled'}
                  data-ano="${d.anoExercicio || ''}"
                  data-total="${(d.valorTotal || '').replace(/\s/g,'')}"
                ><i class="fa-brands fa-pix"></i>
                  Pagar
                </button>
              </td>
            `;
                        tbody.appendChild(tr);
                    });
                }

                if (celularContainer) {
                    celularContainer.innerHTML = '';
                    debitos.forEach((d, idx) => {
                        const habilita = d.valorTotal.includes('R$');
                        const card = document.createElement('div');
                        card.className = `p-4 ${idx % 2 ? 'bg-gray-50' : ''}`;
                        card.innerHTML = `
                            <div class="space-y-2 text-sm">
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">Valor Total (R$):</span>
                                <span class="font-bold ${habilita ? 'text-red-600' : 'text-gray-700'}">${normaliza(d.valorTotal)}</span>
                              </div>
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">IPVA (R$):</span>
                                <span class="${d.valorIpva?.includes('PAGO') || d.valorIpva?.includes('QUITADO') ? 'text-green-600' : 'text-red-600'}">${normaliza(d.valorIpva)}</span>
                              </div>
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">Data de Vencimento:</span>
                                <span class="text-gray-700">${normaliza(d.dataVencimento)}</span>
                              </div>
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">Licenciamento (R$):</span>
                                <span class="${d.valorLicenciamento?.includes('PAGO') ? 'text-green-600' : 'text-red-600'}">${normaliza(d.valorLicenciamento)}</span>
                              </div>
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">Seguro Obrigatório (R$):</span>
                                <span class="text-gray-700">${normaliza(d.valorSeguro)}</span>
                              </div>
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">Infrações (R$):</span>
                                <span class="${d.valorMulta?.startsWith('R$') ? 'text-red-600' : 'text-gray-700'}">${normaliza(d.valorMulta)}</span>
                              </div>
                              <div class="flex justify-between py-1">
                                <span class="font-semibold text-gray-800">Ano / Referência:</span>
                                <span class="text-gray-700">${normaliza(d.anoExercicio)}</span>
                              </div>
                            </div>
                            <button 
                              class="w-full mt-3 ${habilita ? 'bg-primary hover:opacity-90' : 'bg-gray-400 cursor-not-allowed'} text-white py-2 px-4 rounded text-sm font-medium btn-pagar"
                              ${habilita ? '' : 'disabled'}
                              data-ano="${d.anoExercicio || ''}"
                              data-total="${(d.valorTotal || '').replace(/\s/g,'')}"
                            >
                              Pagar
                            </button>
                          `;
                        celularContainer.appendChild(card);
                    });
                }


                document.addEventListener('click', async function(e) {
                    // Verifica se o clique foi em um botão com a classe .btn-pagar
                    const btn = e.target.closest('.btn-pagar');

                    if (!btn || btn.disabled) return;

                    const total = btn.dataset.total;
                     const ano = btn.dataset.ano;

                    document.querySelector('.p-desc').innerHTML = 'IPVA '+ano;

                    await openPixModal(total);
 
                });

